#define HELP_STRING "Controls/options:\n\t*File:\n\t\t-Ctrl-O: Open a comics file (PDF, CBR, CBZ ...)\n\t\t-Ctrl-Q: Quit (preferences will be saved)\n\n\t*Fullscreen:\n\t\t-Ctrl-F: Fullscreen mode on/off\n\n\t*Reading mode:\n\t\t-P: Switch to Page mode: only the full pages are displayed\n\t\t-S: Switch to Strip mode: display in strips mode, based on window/page width\n\t\t-C: Switch to Panel (square) mode: display each panel of the comics individually\nwhen possible\n\t\t-Page preview: Display a preview of the full page when in Panel/Strip mode,\nallowing to preview the whole page before reading in details\n\t\t-Ctrl-T: Show/hide the page thumbnails view (full page view on the side)\n\n\t*Navigation:\n\t\t-Left arrow: Go to previous case/previous strip (to previous page in Page mode)\n\t\t-Right arrow: Go to next case/next strip (to next page in Page mode)\n\t\t-Bottom arrow: Go to previous page\n\t\t-Top arrow: Go to next page\n\t\t-Mouse wheel up: Go to previous case/strip/page\n\t\t-Mouse wheel down: Go to next case/strip/page\n\n"
#define HELP_STRING_HTML "<H1>Controls/options:</H1><BR><H5>&nbsp;&nbsp;&nbsp;*File:</H5><BR>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;-Ctrl-O: Open a comics file (PDF, CBR, CBZ ...)<BR>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;-Ctrl-Q: Quit (preferences will be saved)<BR><BR><H5>&nbsp;&nbsp;&nbsp;*Fullscreen:</H5><BR>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;-Ctrl-F: Fullscreen mode on/off<BR><BR><H5>&nbsp;&nbsp;&nbsp;*Reading mode:</H5><BR>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;-P: Switch to Page mode: only the full pages are displayed<BR>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;-S: Switch to Strip mode: display in strips mode, based on window/page width<BR>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;-C: Switch to Panel (square) mode: display each panel of the comics individually when possible<BR>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;-Page preview: Display a preview of the full page when in Panel/Strip mode, allowing to preview the whole page before reading in details<BR>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;-Ctrl-T: Show/hide the page thumbnails view (full page view on the side)<BR><BR><H5>&nbsp;&nbsp;&nbsp;*Navigation:</H5><BR>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;-Left arrow: Go to previous case/previous strip (to previous page in Page mode)<BR>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;-Right arrow: Go to next case/next strip (to next page in Page mode)<BR>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;-Bottom arrow: Go to previous page<BR>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;-Top arrow: Go to next page<BR>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;-Mouse wheel up: Go to previous case/strip/page<BR>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;-Mouse wheel down: Go to next case/strip/page<BR><BR>"
